  "{x} costs {n} coins.": ["{x}は{n}コイン。", "{x}은(는) {n} 코인이다.", "{x}要{n}金币。", "{x}要{n}金幣。", "{x} giá {n} xu.", "{x} seharga {n} koin.", "{x} ราคา {n} เหรียญ", "{x} {n} altın.", "{x} cuesta {n} monedas.", "{x} custa {n} moedas.", "{x}: стоит {n} монет.", "{x}: коштує {n} монет."],
  "{x}: placed.": ["{x}: 設置した。", "{x}: 배치함.", "{x}:已摆放。", "{x}:已擺放。", "{x}: đã đặt.", "{x}: ditempatkan.", "{x}: วางแล้ว", "{x}: yerleştirildi.", "{x}: colocado.", "{x}: colocado.", "{x}: установлено.", "{x}: встановлено."],
